import matplotlib; matplotlib.use("Agg")
import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch
fig, ax = plt.subplots(figsize=(7.4, 6.4)); ax.set_xlim(0, 10); ax.set_ylim(1.8, 12.4); ax.axis("off")
def box(x, y, w, h, title, body, fc):
    ax.add_patch(FancyBboxPatch((x, y), w, h, boxstyle="round,pad=0.02,rounding_size=0.15", fc=fc, ec="#333", lw=1))
    ax.text(x + w/2, y + h - 0.22, title, ha="center", va="top", fontsize=9.5, weight="bold")
    ax.text(x + w/2, y + h - 0.55, body, ha="center", va="top", fontsize=7.8, linespacing=1.35)
def arrow(x1, y1, x2, y2):
    ax.annotate("", (x2, y2), (x1, y1), arrowprops=dict(arrowstyle="-|>", lw=1.1, color="#333"))
box(0.2, 11.0, 9.6, 1.25, "1. Experimental dataset (n = 44)", "Diesel 23° bTDC × 4 loads (n = 4); MESO-B20 and MEWVO-B20 × 5 timings × 4 loads (n = 20 each)\nInputs: fuel (categorical), injection timing, load   |   Outputs: BTE, BSFC (g/kWh), CO, HC, NOx", "#e8f3e8")
box(0.6, 9.55, 8.8, 1.15, "2. Pre-processing inside each training fold (Pipeline)", "Fuel → one-hot encoding (3 indicators, no ordinal coding)\nSVR only: StandardScaler on timing/load and on the target (TransformedTargetRegressor)", "#e6eef8")
arrow(5, 11.0, 5, 10.7)
box(0.2, 6.75, 4.5, 2.5, "3a. Repeated nested CV (primary)", "Outer: fuel-stratified 4-fold × 10 repeats\n(40 outer test folds of 11 conditions,\none diesel condition per fold)\nInner: 5-fold GridSearchCV on outer-train\n(scoring = RMSE; no early stopping)\nOut-of-fold predictions for all 44 points\n→ R², MAE, RMSE, sMAPE (MAPE suppl.)\nmean ± SD over repeats", "#fdf1e2")
box(5.3, 6.75, 4.5, 2.5, "3b. Supporting validation", "Stratified 80/20 holdout\n(35 train / 9 test) + bootstrap CI\nLeave-boundary-timing-out test\n(train 19–23°, test 17° & 25°, n = 16)\nBaselines: mean, MLR, quadratic ridge,\nrandom forest (same outer folds)", "#fdf1e2")
arrow(3.5, 9.55, 2.45, 9.25); arrow(6.5, 9.55, 7.55, 9.25)
box(0.2, 4.15, 4.5, 2.25, "4a. Models (one per response)", "XGBoost: n_estimators, max_depth,\nlearning_rate, reg_lambda tuned\nSVR: RBF / polynomial / linear\nkernels; C, γ, ε tuned\nFuel handled identically for both", "#f6e6f2")
box(5.3, 4.15, 4.5, 2.25, "4b. Agreement & inference", "Bland–Altman bias and 95% LoA\n(repeat-averaged OOF predictions)\nNadeau–Bengio corrected t-test\n(XGBoost vs SVR fold RMSE)\nFactorial ANOVA: balanced biodiesel\nsub-design; fuel × load at 23° bTDC", "#f6e6f2")
arrow(2.45, 6.75, 2.45, 6.4); arrow(7.55, 6.75, 7.55, 6.4)
box(0.6, 1.95, 8.8, 1.75, "5. Interpretation & reporting", "SHAP global importance (XGBoost: TreeExplainer; SVR: exact KernelExplainer)\nevaluated on outer test folds → mean ± SD over 40 folds\nSHAP dependence (final XGBoost, all 44 points)\nAll tables and figures regenerated by one script (seed = 42)", "#ece8f6")
arrow(2.45, 4.15, 3.6, 3.7); arrow(7.55, 4.15, 6.4, 3.7)
plt.tight_layout(); plt.savefig("Fig_workflow.png", dpi=300)
